AULAS[119] = { ill:'balanca', slides:[
  {type:'capa', title:'Modalização e argumentação', sub:'Como o autor se posiciona no texto'},
  {type:'objetivos', items:['Reconhecer marcas de modalização','Identificar graus de certeza e obrigação','Analisar estratégias argumentativas','Usar modalizadores na escrita']},
  {type:'pergunta', q:'Qual é a diferença: "Vai chover", "Talvez chova" e "É provável que chova"?', hint:'Pense no grau de certeza.', ill:'balao'},
  {type:'conceito', title:'Modalização', text:'**Modalização** são as marcas que mostram a **atitude** de quem escreve: certeza, dúvida, obrigação, avaliação. Ela é essencial na **argumentação**.', box:'Modalizadores podem ser advérbios, verbos, adjetivos e expressões.', ill:'balanca'},
  {type:'exemplos', title:'Tipos de modalização', cards:[['Certeza','certamente, sem dúvida, é evidente'],['Possibilidade','talvez, possivelmente, pode ser'],['Obrigação','é preciso, deve-se, é necessário'],['Avaliação','felizmente, lamentavelmente, é importante']]},
  {type:'texto', title:'Leitura: trecho argumentativo', text:'É evidente que o uso excessivo de telas afeta o sono dos adolescentes. Possivelmente, muitos nem percebem o problema. Por isso, é necessário que as famílias estabeleçam limites. Felizmente, algumas escolas já discutem o tema.', source:'Texto criado para esta aula', side:{h:'Classifique', items:['É EVIDENTE','POSSIVELMENTE','É NECESSÁRIO e FELIZMENTE']}},
  {type:'comparacao', title:'Estratégias argumentativas', left:{h:'Afirmar com força', items:['"Sem dúvida..."','Transmite segurança','Risco de parecer dogmático']}, right:{h:'Atenuar', items:['"Talvez..."','Mostra cautela','Pode enfraquecer a tese']}},
  {type:'passos', title:'Como analisar', steps:[['Ache os modalizadores','Advérbios, verbos'],['Classifique','Certeza, dúvida, obrigação'],['Efeito','O que revelam?'],['Avalie','A argumentação convence?']]},
  {type:'mapa', title:'Mapa mental', center:'MODALIZAÇÃO', nodes:[['Certeza','certamente'],['Possibilidade','talvez'],['Obrigação','é preciso'],['Avaliação','felizmente'],['Posição do autor','Revelada'],['Argumentação','Persuasão']]},
  {type:'atividade', title:'Atividade 1: mude o grau', instr:'Reescreva com o grau indicado.', items:[{q:'A biblioteca vai fechar. (dúvida)', r:'Talvez a biblioteca feche.'},{q:'Os alunos usam o pátio. (obrigação)', r:'Os alunos devem usar o pátio.'},{q:'A reforma terminou. (avaliação positiva)', r:'Felizmente, a reforma terminou.'}]},
  {type:'atividade', title:'Atividade 2: identifique', instr:'Que atitude o modalizador revela?', items:[{q:'Lamentavelmente, o parque foi fechado.', r:'Avaliação negativa'},{q:'Certamente o time vai vencer.', r:'Certeza'},{q:'É preciso economizar água.', r:'Obrigação / necessidade'}]},
  {type:'quiz', q:'"Talvez" expressa...', opts:['certeza','possibilidade','obrigação','tempo'], c:1, why:'Indica dúvida.'},
  {type:'quiz', q:'"É necessário preservar as florestas." O modalizador indica...', opts:['obrigação/necessidade','dúvida','tempo','lugar'], c:0, why:'Expressa necessidade.'},
  {type:'quiz', q:'Modalizadores revelam...', opts:['a atitude do autor','o número de páginas','o gênero do substantivo','a sílaba tônica'], c:0, why:'Mostram como o autor se posiciona.'},
  {type:'gabarito'},
  {type:'resumo', items:['Modalização revela a atitude do autor.','Pode indicar certeza, possibilidade, obrigação, avaliação.','É estratégia argumentativa.','Afirmar ou atenuar produz efeitos diferentes.']},
  {type:'auto', items:['Reconheço modalizadores.','Classifico a atitude.','Analiso o efeito argumentativo.','Uso modalizadores ao escrever.']},
  {type:'encerramento', casa:'Leia um artigo de opinião e sublinhe 4 modalizadores, classificando-os.'}
]};

