AULAS[123] = { ill:'balanca', slides:[
  {type:'capa', title:'Textos legais', sub:'Direitos e deveres'},
  {type:'objetivos', items:['Reconhecer a estrutura de textos normativos e legais','Identificar direitos garantidos e proibições','Compreender o caráter imperativo das leis','Relacionar leis ao cotidiano dos jovens']},
  {type:'pergunta', q:'Você conhece algum direito garantido a crianças e adolescentes por lei?', hint:'Pense no Estatuto da Criança e do Adolescente (ECA).', ill:'balao'},
  {type:'conceito', title:'Textos normativos', text:'Leis, estatutos e regimentos **estabelecem direitos, deveres e proibições**. Têm linguagem **formal e impessoal** e organização em **artigos, parágrafos, incisos e alíneas**.', box:'O ECA (Lei nº 8.069/1990) garante direitos de crianças e adolescentes.', ill:'balanca'},
  {type:'exemplos', title:'Organização', cards:[['Artigo (Art.)','Unidade básica da lei'],['Parágrafo (§)','Complementa ou excepciona o artigo'],['Inciso (I, II, III)','Desdobra o artigo em itens'],['Alínea (a, b, c)','Desdobra o inciso']]},
  {type:'texto', title:'Leitura: trecho do ECA', text:'Art. 53. A criança e o adolescente têm direito à educação, visando ao pleno desenvolvimento de sua pessoa, preparo para o exercício da cidadania e qualificação para o trabalho, assegurando-se-lhes:\nI - igualdade de condições para o acesso e permanência na escola;\nII - direito de ser respeitado por seus educadores;', source:'Estatuto da Criança e do Adolescente, Lei nº 8.069/1990 (trecho)', side:{h:'Analise', items:['Que direito o artigo garante?','O que dizem os incisos I e II?','Que palavras mostram formalidade?']}},
  {type:'comparacao', title:'Direito x proibição', left:{h:'Direito garantido', items:['"têm direito a..."','"é assegurado..."']}, right:{h:'Proibição / dever', items:['"é proibido..."','"deverá..."','"é vedado..."']}},
  {type:'passos', title:'Como ler uma lei', steps:[['Identifique o artigo','Tema central'],['Leia incisos','Detalhamentos'],['Verbos','Garantir, proibir, dever'],['Relacione','Com situações reais']]},
  {type:'mapa', title:'Mapa mental', center:'TEXTOS LEGAIS', nodes:[['Artigo','Unidade básica'],['Parágrafo','§'],['Incisos','I, II, III'],['Direitos','têm direito'],['Proibições','é vedado'],['ECA','Crianças e adolescentes']]},
  {type:'atividade', title:'Atividade 1: direito ou proibição?', instr:'Classifique.', items:[{q:'"É vedada a venda de bebidas alcoólicas a menores de 18 anos."', r:'Proibição'},{q:'"Todo cidadão tem direito à saúde."', r:'Direito'},{q:'"O aluno deverá zelar pelo patrimônio escolar."', r:'Dever'}]},
  {type:'desafio', title:'Desafio: regimento da turma', text:'Escrevam um mini-regimento da turma em formato de lei.', items:['Pelo menos 3 artigos','Um artigo com incisos','Direitos e deveres','Linguagem formal e impessoal'], ill:'check'},
  {type:'quiz', q:'A unidade básica de uma lei é o...', opts:['artigo','capítulo de romance','verso','parágrafo de notícia'], c:0, why:'Leis se organizam em artigos.'},
  {type:'quiz', q:'"É vedado" significa...', opts:['é permitido','é proibido','é recomendado','é opcional'], c:1, why:'Vedado = proibido.'},
  {type:'quiz', q:'O ECA trata dos direitos de...', opts:['consumidores','crianças e adolescentes','idosos','trabalhadores rurais'], c:1, why:'Estatuto da Criança e do Adolescente.'},
  {type:'gabarito'},
  {type:'resumo', items:['Textos legais regulam direitos e deveres.','Organizam-se em artigos, parágrafos e incisos.','Têm linguagem formal e caráter imperativo.','O ECA protege crianças e adolescentes.']},
  {type:'auto', items:['Reconheço a estrutura legal.','Identifico direitos e proibições.','Leio artigos e incisos.','Relaciono leis ao cotidiano.']},
  {type:'encerramento', casa:'Leia outro artigo do ECA e explique com suas palavras o que ele garante.'}
]};

